# *****************************************************************************
# User-configurable settings for mofa_train_glm.R.
#
# This script trains view-specific LASSO/elastic-net models that predict factor
# values learned by a previously fitted MOFA model. All output is written to a
# folder named "glm_model" created beside the model.hdf5 file specified below.
# *****************************************************************************

# Full path to the fitted MOFA model generated by MOFA_analysis.R.
mofa_res_fname <- file.path("D:/R_sessions/PROSPR/MOFA/foo",
		"2026_Sep_23_18_16_57_visit=24mo_change_scores_views=pr+mb",
		"model.hdf5")

# MOFA factors to evaluate. Use "all" to train predictors for every factor, or
# provide a character vector such as c("Factor1", "Factor2").
factors <- "all"

# MOFA data views to evaluate. Use "all" to train predictors for every view, or
# provide a character vector of view names.
views <- "all"

# MOFA factor values are continuous outcomes. "binary" is accepted by the
# training function for completeness but is not the normal MOFA use case.
outcome_type <- "continuous"

# Number of repeated internal train/test splits used to evaluate how well each
# view predicts each factor.
n_repeats <- 20

# Fraction of samples assigned to the training set in each repeated split.
train_frac <- 0.7

# Optional seed for reproducible split/model seeds. Set to NULL for an
# unconstrained random seed.
seed <- 123

# Elastic-net mixing parameter. alpha = 1 corresponds to LASSO.
alpha <- 1

# Penalization value selected from each cv.glmnet fit.
lambda_choice <- "lambda.min"   # alternatively: "lambda.1se"

# If TRUE, glmnet standardizes predictors internally using the training data.
standardize <- TRUE

# Number of folds used by cv.glmnet inside each training fit.
nfolds <- 10

# Minimum matched samples and usable features required to fit a view/factor
# predictor.
min_samples <- 10
min_features <- 2

# Parallelize independent view/factor models using future.apply. Parallelization
# occurs across view/factor combinations; repeated CV within each worker remains
# serial.
use_parallel <- TRUE
n_workers <- 50 #max(1L, parallel::detectCores() - 5L)

# Print progress messages while models are trained.
verbose <- TRUE

# Training-report settings. The report and its supporting CSV tables are written
# into the same glm_model folder as mofa_glm_predictor.rds.
report_file <- "mofa_factor_predictor_training_report.pdf"
include_top_features <- TRUE
top_n_features <- 20
report_width <- 11
report_height <- 8.5
